  const comparison10={generation_id:FIRST_V11_COMPARISON,findings:derived.findings.filter(f=>h.reviews.slice(0,6).some(r=>r.id===f.review_id)),snapshot:{analysis_version:10,reviews:structuredClone(h.reviews),publication:{consultant_report:{...prior,version:10 as const,cross_rating_analysis:derived.cross_rating_analysis,calibrated_analysis_pipeline:{...usage,threshold_version:'jev-theme-thresholds-v1',question_set:'themes_v10_calibrated_v1',thresholds:structuredClone(V11_CONFIG.thresholds),source_generation_id:FIRST_V11_SOURCE,source_snapshot_sha256:'a'.repeat(64),unavailable_theme_reviews:0}}}}}
